import React, { Component } from "react";


export default class MainPage extends Component {

    render() {
        return (
            <div className="about-page">
                <h1>About Us</h1>
                <p>Welcome to MyShop! We are passionate about providing the best products at great prices.</p>

                <h2>Contact Us</h2>
                <p>Email: contact@myshop.com</p>
                <p>Phone: (123) 456-7890</p>

                <h2>Our Mission</h2>
                <p>Our goal is to offer the best quality products and exceptional customer service. Thank you for shopping with us!</p>
            </div>
        );
    }
}
